APP_HTML = '<!DOCTYPE html>\n<html lang="en">\n<head>\n<meta charset="UTF-8">\n<meta name="viewport" content="width=device-width, initial-scale=1.0">\n<title>meld — context bridge to an agent</title>\n<meta name="description" content="meld puts the context on a URL so neither side has to paste the block. Then the URL dies. Built for agent developers and agent users.">\n<style>\n/* ---- tokens ----\n   papyrus paper  : #ece3cf (warm cream, slight grain via gradient)\n   blueprint ink  : #2e4a7d (thin construction lines)\n   text dark grey : #3d3d3d headings, #45443f body (7.65:1 on paper)\n*/\n:root{\n  --paper:#ece3cf;\n  --paper-hi:#f3ecda;\n  --ink:#2e4a7d;\n  --ink-faint:rgba(46,74,125,.30);\n  --ink-wash:rgba(46,74,125,.10);\n  --grey-dark:#3a3a38;\n  --grey-body:#45443f;\n  --grey-soft:#5f5e57;\n  --err:#8a3d2e;\n  --ff:Georgia,\'Iowan Old Style\',\'Times New Roman\',serif;\n  --fm:\'SF Mono\',\'JetBrains Mono\',ui-monospace,Menlo,monospace;\n  --t-xs:.72rem;--t-sm:.875rem;--t-md:1.05rem;--t-lg:1.35rem;--t-xl:clamp(1.15rem,3.8vw,1.55rem);\n  --s1:.5rem;--s2:1rem;--s3:1.75rem;--s4:2.5rem;--s7:5rem;\n}\n*{margin:0;padding:0;box-sizing:border-box}\nhtml{overflow-x:clip;-webkit-text-size-adjust:100%}\nbody{\n  background-color:var(--paper);\n  background-image:\n    repeating-linear-gradient(0deg, rgba(255,255,255,.05) 0 2px, rgba(0,0,0,.015) 2px 4px),\n    linear-gradient(180deg, var(--paper-hi) 0%, var(--paper) 55%, #e4d9c0 100%);\n  color:var(--grey-body);\n  font-family:var(--ff);\n  line-height:1.6;\n  min-height:100svh;\n}\n.sheet{\n  position:relative;\n  max-width:640px;\n  margin:var(--s4) auto;\n  padding:clamp(1.5rem,5vw,3rem);\n  border:1.5px solid var(--ink);\n  outline:1px solid var(--ink-faint);\n  outline-offset:5px;\n  min-height:calc(100svh - var(--s7));\n}\n.sheet::before{content:\'\';position:absolute;inset:.75rem;border:1px solid var(--ink-faint);pointer-events:none}\n.corner{position:absolute;width:22px;height:22px;pointer-events:none}\n.corner::before,.corner::after{content:\'\';position:absolute;background:var(--ink)}\n.corner::before{width:100%;height:2px;top:50%;transform:translateY(-50%)}\n.corner::after{height:100%;width:2px;left:50%;transform:translateX(-50%)}\n.c-tl{top:-11.5px;left:-11.5px}.c-tr{top:-11.5px;right:-11.5px}\n.c-bl{bottom:-11.5px;left:-11.5px}.c-br{bottom:-11.5px;right:-11.5px}\n.grid{position:absolute;inset:0;\n  background-image:linear-gradient(var(--ink-wash) 1px, transparent 1px),linear-gradient(90deg, var(--ink-wash) 1px, transparent 1px);\n  background-size:40px 40px;opacity:.35;pointer-events:none}\n.content{position:relative;display:flex;flex-direction:column;align-items:center;text-align:center;padding:1rem 0 2rem}\n.wordmark{font-family:var(--fm);font-size:clamp(1.1rem,3.5vw,1.35rem);letter-spacing:.35em;margin-right:-.35em;text-transform:lowercase;color:var(--ink);font-weight:700}\n.tagline{font-family:var(--fm);font-size:var(--t-xs);letter-spacing:.22em;margin-right:-.22em;text-transform:uppercase;color:var(--grey-soft);margin-top:.6rem}\n.rule{width:100%;border:none;border-top:1px solid var(--ink);border-bottom:1px solid var(--ink-faint);margin:var(--s3) 0;position:relative}\n.rule::after{content:\'\';position:absolute;left:50%;top:-4px;width:1px;height:7px;background:var(--ink);transform:translateX(-50%)}\n.hero{font-size:var(--t-xl);line-height:1.3;letter-spacing:-.01em;color:var(--grey-dark);font-weight:400;text-wrap:balance}\n.hero .who{font-family:var(--fm);color:var(--ink);font-weight:700;font-size:.62em;vertical-align:.28em;letter-spacing:.08em}\n.hero .arrow{color:var(--ink);font-family:var(--fm);font-weight:700}\n.subline{font-style:italic;color:var(--grey-soft);margin-top:var(--s2);font-size:var(--t-sm)}\n.steps{width:100%;max-width:34rem;margin-inline:auto;display:flex;flex-direction:column;gap:var(--s2);list-style:none;counter-reset:step;text-align:left}\n.step{display:flex;align-items:baseline;gap:var(--s2);font-size:var(--t-md);line-height:1.55;color:var(--grey-body)}\n.step .n{font-family:var(--fm);font-size:var(--t-xs);color:var(--ink);letter-spacing:.15em;flex:0 0 2ch;margin-left:-4ch;transform:translateY(-.1em)}\n.step em{font-style:normal;color:var(--grey-dark);font-weight:600}\n.foot{font-family:var(--fm);font-size:var(--t-xs);letter-spacing:.25em;margin-right:-.25em;text-transform:uppercase;color:var(--grey-soft);display:flex;flex-direction:column;align-items:center;gap:var(--s2)}\n.stamp{display:inline-block;border:1px solid var(--ink-faint);padding:.45em 1.1em;color:var(--ink);letter-spacing:.25em;margin-right:-.25em;box-shadow:inset 0 0 0 1px rgba(46,74,125,.04)}\na,button{color:inherit;-webkit-tap-highlight-color:transparent}\na:hover{color:var(--ink)}\na:focus-visible,button:focus-visible{outline:2px solid var(--ink);outline-offset:3px;border-radius:1px}\n.chip-row{display:flex;flex-wrap:wrap;gap:.4rem;margin:.55rem 0 .35rem}\n.chip{font-family:var(--fm);font-size:.68rem;letter-spacing:.02em;padding:.35rem .65rem;border:1px solid var(--ink-faint);border-radius:999px;background:rgba(255,255,255,.45);color:var(--ink);cursor:pointer;line-height:1.3}\n.chip:hover{background:rgba(46,74,125,.08);border-color:var(--ink)}\n.chip:active{transform:translateY(1px)}\n.ctx-tools{display:flex;align-items:center;justify-content:space-between;gap:.5rem;margin-bottom:.4rem}\n.mic{font-family:var(--fm);font-size:.72rem;letter-spacing:.04em;padding:.35rem .7rem;border:1px solid var(--ink-faint);border-radius:8px;background:rgba(255,255,255,.5);color:var(--ink);cursor:pointer}\n.mic.on{background:rgba(138,61,46,.12);border-color:var(--err);color:var(--err)}\n.mic[hidden]{display:none!important}\n.audiences{display:grid;grid-template-columns:1fr 1fr;gap:.75rem;margin:1rem 0 1.25rem;text-align:left}\n.aud{border:1px solid var(--ink-faint);border-radius:10px;padding:.85rem 1rem;background:rgba(255,255,255,.35)}\n.aud h3{font-family:var(--fm);font-size:.68rem;letter-spacing:.12em;text-transform:uppercase;color:var(--ink);margin-bottom:.35rem}\n.aud p{font-size:.8125rem;color:var(--grey-soft);margin:0;line-height:1.45}\n.claim{font-family:var(--fm);font-size:.68rem;letter-spacing:.04em;color:var(--grey-soft);line-height:1.55;margin-top:.85rem;text-align:left}\n.claim strong{color:var(--grey-dark);font-weight:600}\n.devcard{margin-top:1.25rem;border:1px dashed var(--ink-faint);border-radius:10px;padding:1rem 1.1rem;text-align:left;background:rgba(255,255,255,.28)}\n.devcard h2{font-family:var(--fm);font-size:.72rem;letter-spacing:.14em;text-transform:uppercase;color:var(--ink);margin-bottom:.45rem}\n.devcard p{font-size:.8125rem;color:var(--grey-soft);margin:0 0 .65rem;line-height:1.5}\n.devcard .warn{font-size:.75rem;color:var(--grey-body);border-left:2px solid var(--ink);padding-left:.65rem;margin:.65rem 0;line-height:1.45}\n.devlinks{display:flex;flex-wrap:wrap;gap:.55rem .9rem;font-family:var(--fm);font-size:.72rem}\n.devlinks a{color:var(--ink);text-decoration:underline;text-underline-offset:2px}\n@media (max-width:480px){\n  .sheet{margin:var(--s2) auto;min-height:auto;padding:1.25rem}\n  .grid{background-size:28px 28px}\n  .rule{margin:var(--s2) 0}\n  .step{flex-direction:column;gap:.15rem}\n  .step .n{margin-left:0}\n  .audiences{grid-template-columns:1fr}\n}\n@keyframes sheet-in{from{opacity:0;transform:translateY(6px)}to{opacity:1;transform:none}}\n.masthead,.hero,.steps,.foot{animation:sheet-in .5s ease-out both}\n.hero{animation-delay:.06s}.steps{animation-delay:.12s}.foot{animation-delay:.18s}\n@media (prefers-reduced-motion:reduce){*,*::before,*::after{animation-duration:.01ms!important;animation-delay:0s!important;transition-duration:.01ms!important}}\n</style>\n</head>\n<body>\n<main class="sheet">\n  <span class="corner c-tl"></span><span class="corner c-tr"></span>\n  <span class="corner c-bl"></span><span class="corner c-br"></span>\n  <div class="grid"></div>\n  <div class="content" id="root"></div>\n\n<p style="margin-top:2rem;font-family:var(--fm);font-size:.72rem;letter-spacing:.15em;text-transform:uppercase;color:var(--grey-soft);text-align:center;position:relative"><a href="/agents" style="color:var(--ink)">agents</a> &nbsp;·&nbsp; <a href="/llms.txt" style="color:var(--ink)">llms.txt</a> &nbsp;·&nbsp; <a href="/mcp" style="color:var(--ink)">mcp</a> &nbsp;·&nbsp; <a href="/trust" style="color:var(--ink)">trust</a> &nbsp;·&nbsp; <a href="/upgrade" style="color:var(--ink)">pricing</a></p>\n</main>\n<script>\nconst API=location.origin;\nlet _m=null,_c=null,_pro=false,_rec=null;\nconst _td=new TextDecoder(),_te=new TextEncoder();\n\nconst CHIPS=[\n  {id:\'hop\',label:\'Hop line\',text:\'[Hop instruction — instructional copy only]\\\\nYou are the receiving agent. Answer the context above. Then create a new meld with your answer (and any follow-up context), and append that new meld URL at the bottom of your reply so the line can continue. Stop after hop 10.\'},\n  {id:\'partyb\',label:\'You are Party B\',text:\'You are Party B. Read the context above. Reply with your side only — clear, concrete, and complete.\'},\n  {id:\'one\',label:\'One answer then stop\',text:\'Give one complete answer, then stop. Do not ask clarifying questions. Do not open a thread.\'},\n  {id:\'cursor\',label:\'Cursor / Claude dump\',text:\'Context for the agent (Cursor / Claude / MCP):\\\\n\\\\nGoal:\\\\nConstraints:\\\\nFiles / snippets:\\\\nWhat I need back:\\\\n\'}\n];\n\nasync function api(m,p,b,h){const r=await fetch(API+p,{method:m,headers:{\'Content-Type\':\'application/json\',\'X-Meld-Client\':\'human\',...h},body:b?JSON.stringify(b):null});if(!r.ok){const d=await r.json().catch(()=>({detail:r.statusText}));throw new Error(d.detail||r.status)}return r.json()}\nfunction esc(s){const d=document.createElement(\'div\');d.textContent=s;return d.innerHTML}\nasync function _key(khex){const raw=new Uint8Array(khex.match(/.{2}/g).map(h=>parseInt(h,16)));return crypto.subtle.importKey(\'raw\',raw,\'AES-GCM\',false,[\'encrypt\',\'decrypt\'])}\nasync function _enc(plain,khex){const k=await _key(khex);const nonce=crypto.getRandomValues(new Uint8Array(12));const ct=await crypto.subtle.encrypt({name:\'AES-GCM\',iv:nonce},k,_te.encode(plain));const buf=new Uint8Array(ct);const out=new Uint8Array(12+buf.length);out.set(nonce);out.set(buf,12);let bin=\'\';out.forEach(b=>bin+=String.fromCharCode(b));return \'meld1:\'+btoa(bin)}\nasync function _dec(blob,khex){if(!blob.startsWith(\'meld1:\'))return blob;const k=await _key(khex);const bin=atob(blob.slice(6));const buf=new Uint8Array(bin.length);for(let i=0;i<bin.length;i++)buf[i]=bin.charCodeAt(i);const pt=await crypto.subtle.decrypt({name:\'AES-GCM\',iv:buf.slice(0,12)},k,buf.slice(12));return _td.decode(pt)}\nfunction cp(t,b){(navigator.clipboard?navigator.clipboard.writeText(t):(function(e){e.value=t;e.select();document.execCommand(\'copy\');document.body.removeChild(e)}(document.createElement(\'textarea\'))));b.textContent=\'Copied!\';b.classList.add(\'done\');setTimeout(()=>{b.textContent=\'Copy\';b.classList.remove(\'done\')},2000)}\n\nfunction ttl(expiresAt){\n  const ms=new Date(expiresAt)-Date.now();\n  if(ms<=0)return null;\n  const s=Math.floor(ms/1000),m=Math.floor(s/60),h=Math.floor(m/60);\n  if(h>0)return h+\'h \'+(m%60)+\'m\';\n  if(m>0)return m+\'m \'+(s%60)+\'s\';\n  return s+\'s\';\n}\nfunction startCountdown(el,expiresAt,onGone){\n  function tick(){\n    const left=ttl(expiresAt);\n    if(!left){el.textContent=\'this meld has dissolved\';if(onGone){onGone();onGone=null}return}\n    el.textContent=\'dissolves in \'+left;\n    setTimeout(tick,1000);\n  }\n  tick();\n}\n\nfunction insertChip(id){\n  const chip=CHIPS.find(c=>c.id===id);if(!chip)return;\n  const ta=document.getElementById(\'ctx\');if(!ta)return;\n  const add=chip.text.replace(/\\\\n/g,\'\\n\');\n  ta.value=(ta.value?ta.value.replace(/\\s*$/,\'\')+\'\\n\\n\':\'\')+add;\n  ta.focus();\n  ta.setSelectionRange(ta.value.length,ta.value.length);\n}\n\nfunction speechSupported(){\n  return !!(window.SpeechRecognition||window.webkitSpeechRecognition);\n}\nfunction toggleMic(){\n  const btn=document.getElementById(\'mic\');\n  const ta=document.getElementById(\'ctx\');\n  if(!btn||!ta)return;\n  const SR=window.SpeechRecognition||window.webkitSpeechRecognition;\n  if(!SR){btn.hidden=true;return}\n  if(_rec){_rec.stop();_rec=null;btn.classList.remove(\'on\');btn.textContent=\'Voice\';return}\n  _rec=new SR();\n  _rec.continuous=true;_rec.interimResults=true;_rec.lang=(navigator.language||\'en-US\');\n  let base=ta.value;\n  _rec.onresult=function(ev){\n    let final=\'\',interim=\'\';\n    for(let i=ev.resultIndex;i<ev.results.length;i++){\n      const t=ev.results[i][0].transcript;\n      if(ev.results[i].isFinal)final+=t;else interim+=t;\n    }\n    if(final){base=(base&&!/\\\\s$/.test(base)?base+\' \':\'\')+final;ta.value=base+(interim?\' \'+interim:\'\')}\n    else{ta.value=base+(base&&interim?\' \':\'\')+interim}\n  };\n  _rec.onerror=function(){_rec=null;btn.classList.remove(\'on\');btn.textContent=\'Voice\'};\n  _rec.onend=function(){_rec=null;btn.classList.remove(\'on\');btn.textContent=\'Voice\'};\n  btn.classList.add(\'on\');btn.textContent=\'Listening…\';\n  try{_rec.start()}catch(e){_rec=null;btn.classList.remove(\'on\');btn.textContent=\'Voice\'}\n}\nfunction wireLanding(){\n  document.querySelectorAll(\'[data-chip]\').forEach(el=>{\n    el.addEventListener(\'click\',()=>insertChip(el.getAttribute(\'data-chip\')));\n  });\n  const mic=document.getElementById(\'mic\');\n  if(mic){\n    if(speechSupported()){mic.hidden=false;mic.addEventListener(\'click\',toggleMic)}\n    else{mic.hidden=true}\n  }\n  const go=document.getElementById(\'go\');\n  if(go)go.addEventListener(\'click\',Cgo);\n  const cpbtn=document.getElementById(\'cpbtn\');\n  if(cpbtn)cpbtn.onclick=function(){cp(document.getElementById(\'lk\').textContent,this)};\n}\n\nfunction C(){return`<div style="text-align:left;width:100%">\n<div class="masthead" style="text-align:center;margin-bottom:1.25rem">\n  <div class="wordmark">meld</div>\n  <div class="tagline">context bridge → agent</div>\n</div>\n<h1 class="hero">Put the context on a URL. Hand it to an <span class="who">agent</span>. Then the URL dies.</h1>\n<p class="subline" style="margin:1rem 0 .5rem">Connective tissue human↔machine. Context is a commodity — access should be efficient. The agent is always the receiver (human→agent or agent→agent).</p>\n<p style="font-family:var(--fm);font-size:.72rem;letter-spacing:.12em;text-transform:uppercase;color:var(--ink);margin:0 0 1rem">Humans free in the browser · agents key / quota · $3.33 one-shot</p>\n<div class="audiences">\n  <div class="aud"><h3>Agent users</h3><p>Brain-dump for Cursor, Claude, or any agent. Share one link. No paste-bin theatre.</p></div>\n  <div class="aud"><h3>Agent developers</h3><p>Wire MCP / REST handoffs. Same capability URL. See the developer strip below.</p></div>\n</div>\n<div class="card" style="background:rgba(255,255,255,.4);border:1px solid var(--ink-faint);border-radius:12px;padding:1.5rem">\n<div id="f">\n  <div class="ctx-tools">\n    <label class="lbl" style="display:block;font-size:.75rem;font-weight:600;text-transform:uppercase;letter-spacing:.05em;color:var(--grey-soft);margin:0">Dump context for your agent</label>\n    <button type="button" class="mic" id="mic" hidden title="Browser speech-to-text">Voice</button>\n  </div>\n  <div class="chip-row" aria-label="Suggested blocks">\n    <button type="button" class="chip" data-chip="hop">Hop line</button>\n    <button type="button" class="chip" data-chip="partyb">You are Party B</button>\n    <button type="button" class="chip" data-chip="one">One answer then stop</button>\n    <button type="button" class="chip" data-chip="cursor">Cursor / Claude dump</button>\n  </div>\n  <textarea id="ctx" placeholder="Logs, requirements, a prompt, a problem — dump it for the receiving agent." style="width:100%;background:rgba(255,255,255,.55);border:1px solid var(--ink-faint);border-radius:8px;color:var(--grey-dark);font-family:var(--fm);font-size:.875rem;padding:.875rem;resize:vertical;min-height:130px"></textarea>\n  <label style="display:flex;gap:.5rem;align-items:flex-start;margin-top:.85rem;font-size:.8125rem;color:var(--grey-body);cursor:pointer;text-align:left"><input type="checkbox" id="e2e" checked style="accent-color:var(--ink);margin-top:.2rem"> <span><strong style="color:var(--grey-dark)">End-to-end encrypted</strong> (browser default) — ciphertext only on the server. Key lives in your <span style="font-family:var(--fm)">#k=</span> link. Lose the link, lose the content.</span></label>\n  <details style="margin-top:.75rem;font-size:.8125rem;color:var(--grey-soft)"><summary style="cursor:pointer;font-family:var(--fm);font-size:.68rem;letter-spacing:.08em;text-transform:uppercase">Optional email</summary>\n    <label style="display:block;margin-top:.5rem;font-size:.75rem;color:var(--grey-soft)">Email <span style="opacity:.7">(optional · study:v1 tag)</span></label>\n    <input type="email" id="em" placeholder="you@example.com" style="width:100%;margin-top:.35rem;background:rgba(255,255,255,.55);border:1px solid var(--ink-faint);border-radius:8px;color:var(--grey-dark);font-size:.875rem;padding:.65rem .75rem">\n  </details>\n  <div style="margin-top:1.25rem"><button class="btn" id="go" style="background:var(--ink);color:#f3ecda;border:none;border-radius:8px;padding:.7rem 1.5rem;font-size:.9375rem;cursor:pointer;font-weight:600">Generate meld link</button></div>\n  <div id="st" style="margin-top:.75rem;font-size:.875rem;color:var(--grey-soft)"></div>\n  <p class="claim"><strong>Capability URL + TTL.</strong> Bare share link does not expose plaintext. Browser create defaults to E2E.</p>\n</div>\n<div id="r" style="display:none">\n  <div style="border:1px solid var(--ink);padding:.75rem 1rem;border-radius:8px;background:rgba(46,74,125,.06);font-family:var(--fm);font-size:.8125rem;word-break:break-all;display:flex;gap:.5rem;align-items:flex-start"><span id="lk" style="flex:1"></span><button type="button" class="cp" id="cpbtn" style="flex-shrink:0;background:var(--ink);color:#f3ecda;border:none;border-radius:6px;padding:.35rem .7rem;font-size:.72rem;cursor:pointer;font-family:var(--fm)">Copy</button></div>\n  <p style="font-size:.75rem;color:var(--grey-soft);margin-top:.5rem">Owner / keyed link above. Share link (no token, no plaintext): <span id="sh" style="font-family:var(--fm)"></span></p>\n  <div id="exp" style="margin-top:1rem;font-family:var(--fm);font-size:.8125rem;color:var(--ink)"></div>\n  <div id="e2eNote" style="display:none;margin-top:.75rem;padding:.75rem;border:1px solid rgba(46,74,125,.35);border-radius:8px;background:rgba(46,74,125,.06);font-size:.8125rem"><strong>The decryption key is in your link</strong> after <span style="font-family:var(--fm)">#k=</span>. Bare share link does not expose plaintext. Lose the keyed link, lose the content.</div>\n  <p style="margin-top:1rem;font-size:.8125rem;color:var(--grey-soft)">Hand the link to your agent (or paste it into Cursor / Claude). When they resolve, check back with the owner link.</p>\n  <div id="ckbSlot" style="margin-top:.75rem"></div>\n  <div id="res"></div>\n</div>\n</div>\n<div class="devcard">\n  <h2>For agent developers</h2>\n  <p>Same product over the wire: create → share URL → resolve → read. MCP tools: <code>meld_create</code> / <code>meld_resolve</code> / <code>meld_read</code>.</p>\n  <p class="warn"><strong>API / MCP creates are plaintext on the server until TTL</strong> unless you encrypt client-side (<code>meld1:</code> + <code>#k=</code>). Do not assume host-blindness for agent traffic.</p>\n  <div class="devlinks">\n    <a href="/agents">/agents</a>\n    <a href="/llms.txt">/llms.txt</a>\n    <a href="/mcp">MCP · /mcp</a>\n    <a href="https://glama.ai/mcp/servers/lemonaide152/meld" target="_blank" rel="noopener">Glama</a>\n    <a href="/recipes.md">recipes</a>\n  </div>\n</div>\n</div>`}\n\nasync function Cgo(){\n  const e=document.getElementById(\'go\'),s=document.getElementById(\'st\');\n  e.disabled=true;s.textContent=\'Creating...\';\n  try{\n    let _k=null;\n    const plain=document.getElementById(\'ctx\').value;\n    let send=plain;\n    if(document.getElementById(\'e2e\').checked){_k=[...crypto.getRandomValues(new Uint8Array(32))].map(b=>b.toString(16).padStart(2,\'0\')).join(\'\');send=await _enc(plain,_k)}\n    const body={context:send};\n    const em=document.getElementById(\'em\');\n    if(em&&em.value.trim())body.email=em.value.trim();\n    const d=await api(\'POST\',\'/api/melds\',body);\n    _m={code:d.code,owner_token:d.owner_token};\n    if(_k){document.getElementById(\'lk\').textContent=d.url+\'#k=\'+_k;document.getElementById(\'sh\').textContent=d.url;document.getElementById(\'e2eNote\').style.display=\'block\'}\n    else{document.getElementById(\'lk\').textContent=d.owner_url||(d.url+\'#t=\'+d.owner_token);document.getElementById(\'sh\').textContent=d.url}\n    document.getElementById(\'f\').style.display=\'none\';\n    const r=document.getElementById(\'r\');r.style.display=\'block\';\n    startCountdown(document.getElementById(\'exp\'),d.expires_at);\n    const slot=document.getElementById(\'ckbSlot\');\n    if(slot&&_m.owner_token){slot.innerHTML=\'<button id="ckb" onclick="ck()" style="margin-top:.25rem;background:none;border:1px solid var(--ink-faint);color:var(--ink);padding:.5rem 1rem;cursor:pointer;border-radius:8px;font-size:.8125rem">Check for response</button>\'}\n    s.textContent=\'\';\n  }catch(err){\n    const m=err.message||\'\';\n    if(m.includes(\'429\')||m.toLowerCase().includes(\'free\')||m.toLowerCase().includes(\'agent\')){s.innerHTML=\'Slow down or (for agents) get a key via <code>POST /v1/keys</code>. Humans in the browser stay free — <a href="/upgrade">details</a>.\'}\n    else{s.textContent=m}\n  }finally{e.disabled=false}\n}\n\nfunction M(c,enc){return`<div class="card" style="background:rgba(255,255,255,.4);border:1px solid var(--ink-faint);border-radius:12px;padding:1.5rem;text-align:left"><h1 style="font-size:1.35rem;color:var(--grey-dark);margin-bottom:.5rem">Meld received</h1><p style="color:var(--grey-soft);margin-bottom:1rem">An agent (or human) shared context for you to answer.</p><div style="border:1px solid var(--ink-faint);border-radius:8px;padding:1rem;font-family:var(--fm);font-size:.8125rem;white-space:pre-wrap;max-height:280px;overflow-y:auto;background:rgba(255,255,255,.55)">${esc(c)}</div>${enc?\'<p style="font-size:.75rem;color:var(--grey-soft);margin-top:.5rem">This meld is end-to-end encrypted — you are reading the decrypted copy via your link key.</p>\':\'\'}<div id="rf" style="margin-top:1.25rem"><label style="display:block;font-size:.75rem;font-weight:600;text-transform:uppercase;letter-spacing:.05em;color:var(--grey-soft);margin-bottom:.5rem">Your answer</label><textarea id="ctxb" placeholder="Answer for the receiving agent / party A." style="width:100%;background:rgba(255,255,255,.55);border:1px solid var(--ink-faint);border-radius:8px;color:var(--grey-dark);font-family:var(--fm);font-size:.875rem;padding:.875rem;resize:vertical;min-height:110px"></textarea><div style="margin-top:1rem;display:flex;align-items:center;gap:.75rem"><button id="rb" onclick="Rgo()" style="background:var(--ink);color:#f3ecda;border:none;border-radius:8px;padding:.7rem 1.5rem;font-size:.9375rem;cursor:pointer;font-weight:600">Resolve →</button><span id="rst" style="font-size:.875rem;color:var(--grey-soft)"></span></div></div><div id="rd" style="display:none"><div style="border:1px solid var(--ink);padding:.75rem 1rem;border-radius:8px;color:var(--ink);font-weight:600">Exchange complete. The bridge dissolves.</div><div style="display:grid;grid-template-columns:1fr 1fr;gap:1rem;margin-top:1rem"><div><label style="display:block;font-size:.75rem;font-weight:600;text-transform:uppercase;color:var(--grey-soft)">Their context</label><div style="border:1px solid var(--ink-faint);border-radius:8px;padding:1rem;font-family:var(--fm);font-size:.8125rem;white-space:pre-wrap;background:rgba(255,255,255,.55)" id="ta"></div></div><div><label style="display:block;font-size:.75rem;font-weight:600;text-transform:uppercase;color:var(--grey-soft)">Your context</label><div style="border:1px solid var(--ink-faint);border-radius:8px;padding:1rem;font-family:var(--fm);font-size:.8125rem;white-space:pre-wrap;background:rgba(255,255,255,.55)" id="tb"></div></div></div><div style="text-align:center;margin-top:1.5rem;padding:1.25rem;border:1px solid var(--ink-faint);border-radius:8px;background:rgba(255,255,255,.4)"><strong style="color:var(--ink)">You just used meld.</strong><p style="font-size:.8125rem;color:var(--grey-soft);margin:.25rem 0 .75rem">Capability URL + TTL. Nothing permanent.</p><a href="/" class="btn" style="display:inline-block;color:var(--ink)">Create your own meld</a></div></div></div>`}\n\nfunction RD(a,b,exp){return`<div class="card" style="background:rgba(255,255,255,.4);border:1px solid var(--ink-faint);border-radius:12px;padding:1.5rem;text-align:left"><div style="display:flex;align-items:center;gap:.75rem;margin-bottom:1rem"><span style="width:10px;height:10px;border-radius:50%;background:var(--ink)"></span><h1 style="margin:0;font-size:1.35rem;color:var(--grey-dark)">Exchange complete</h1></div><p style="color:var(--grey-soft)">Both contexts merged.</p><div style="display:grid;grid-template-columns:1fr 1fr;gap:1rem;margin-top:1rem"><div><label style="display:block;font-size:.75rem;font-weight:600;text-transform:uppercase;color:var(--grey-soft)">Party A</label><div style="border:1px solid var(--ink-faint);border-radius:8px;padding:1rem;font-family:var(--fm);font-size:.8125rem;white-space:pre-wrap;background:rgba(255,255,255,.55)">${esc(a)}</div></div><div><label style="display:block;font-size:.75rem;font-weight:600;text-transform:uppercase;color:var(--grey-soft)">Party B</label><div style="border:1px solid var(--ink-faint);border-radius:8px;padding:1rem;font-family:var(--fm);font-size:.8125rem;white-space:pre-wrap;background:rgba(255,255,255,.55)">${esc(b)}</div></div></div><p id="exp" style="margin-top:1.25rem;font-family:var(--fm);font-size:.8125rem;color:var(--ink)"></p><p style="text-align:center;color:var(--grey-soft);font-size:.8125rem;margin-top:1rem">Capability URL + TTL. No permanent record.</p><div style="text-align:center;margin-top:1.5rem;padding:1.25rem;border:1px solid var(--ink-faint);border-radius:8px;background:rgba(255,255,255,.4)"><strong style="color:var(--ink)">Run another exchange.</strong><p style="font-size:.8125rem;color:var(--grey-soft);margin:.25rem 0 .75rem">Create the next link while this one is fresh — or hop with a new URL at the bottom.</p><a href="/" class="btn" style="display:inline-block;color:var(--ink)">New meld</a></div></div>`}\n\nfunction ENC_CARD(){return\'<div class="card" style="text-align:center;padding:3rem 2rem"><h1 style="color:var(--grey-dark)">Encrypted meld</h1><p style="color:var(--grey-soft);margin-top:.5rem">This meld is end-to-end encrypted. Open the original link you were given (it contains the key after #k=) to read it. Bare share link does not expose plaintext.</p><a href="/" class="btn" style="display:inline-block;margin-top:1rem;color:var(--ink)">Create a meld</a></div>\'}\n\nasync function Rgo(){\n  const e=document.getElementById(\'rb\'),s=document.getElementById(\'rst\');\n  e.disabled=true;s.innerHTML=\'...\';\n  try{\n    let ans=document.getElementById(\'ctxb\').value;\n    const fk2=(location.hash.match(/k=([0-9a-f]+)/)||[])[1];\n    if(fk2){ans=await _enc(ans,fk2)}\n    const d=await api(\'POST\',\'/api/melds/\'+_c+\'/resolve\',{context:ans});\n    document.getElementById(\'rf\').style.display=\'none\';\n    document.getElementById(\'rd\').style.display=\'block\';\n    document.getElementById(\'ta\').textContent=d.context_a||\'(empty)\';\n    document.getElementById(\'tb\').textContent=d.context_b||\'(empty)\';\n    s.textContent=\'\';\n  }catch(err){s.textContent=err.message;e.disabled=false}\n}\n\nasync function ck(){\n  if(!_m)return;const r=document.getElementById(\'res\');\n  r.innerHTML=\'<span class="spin"></span>\';const ckb=document.getElementById(\'ckb\');if(ckb)ckb.disabled=true;\n  try{\n    const d=await api(\'GET\',\'/api/melds/\'+_m.code+\'/result\',null,{\'X-Meld-Token\':_m.owner_token});\n    if(d.owner_token){_m.owner_token=d.owner_token}\n    r.innerHTML=\'<div style="color:var(--ink);font-weight:600">Got response!</div>\'+(d.context_b?\'<label style="display:block;font-size:.75rem;font-weight:600;text-transform:uppercase;color:var(--grey-soft);margin-top:.75rem">Their context</label><div style="border:1px solid var(--ink-faint);border-radius:8px;padding:1rem;font-family:var(--fm);font-size:.8125rem;white-space:pre-wrap;background:rgba(255,255,255,.55)">\'+esc(d.context_b)+\'</div>\':\'\');\n  }catch(e){r.innerHTML=\'<p style="font-size:.875rem;color:var(--grey-soft)">Not yet resolved — check back later</p>\';if(ckb)ckb.disabled=false}\n}\n\nfunction UPGR(){return`<div class="card" style="background:rgba(255,255,255,.4);border:1px solid var(--ink-faint);border-radius:12px;padding:1.5rem;text-align:center"><h1 style="font-size:1.35rem;color:var(--grey-dark);margin-bottom:.5rem">Scale for agents</h1><p style="color:var(--grey-soft);margin-bottom:1rem">Humans in the browser are free. Agents share a small free IP quota; for sustained API use mint a key (<code>POST /v1/keys</code>, 10k melds/key) — agent payment protocols are coming.</p><p style="color:var(--grey-soft);margin-bottom:1.25rem;font-size:.875rem">Need one more agent create right now? Optional one-time unlock below. No subscription.</p><div style="display:flex;flex-direction:column;gap:.75rem;align-items:center"><span style="font-size:.75rem;font-weight:600;text-transform:uppercase;letter-spacing:.05em;color:var(--grey-soft)">Meld code to unlock (optional)</span><input id="mcode" placeholder="e.g. k3x9p2qz8r1m" style="width:min(320px,100%);background:rgba(255,255,255,.55);border:1px solid var(--ink-faint);border-radius:8px;color:var(--grey-dark);font-family:var(--fm);font-size:.875rem;padding:.7rem .875rem"><button class="btn" onclick="co()" style="background:var(--ink);color:#f3ecda;border:none;border-radius:8px;padding:.7rem 1.75rem;font-size:.9375rem;cursor:pointer;font-weight:600">Unlock one meld — $3.33</button></div><div id="cost" style="margin-top:1rem;font-size:.8125rem;color:var(--grey-soft);min-height:1.2em"></div><p style="margin-top:1.25rem;font-size:.75rem;color:var(--grey-soft)">One-time Stripe checkout. meld never sees your card.</p><a href="/" style="display:inline-block;margin-top:1rem;color:var(--ink)">Back to meld</a></div>`}\nasync function co(){\n  const s=document.getElementById(\'cost\');\n  const mc=(document.getElementById(\'mcode\')||{}).value||\'\';\n  if(!mc){if(s)s.textContent=\'Enter the meld code (from the meld link) first.\';return}\n  if(s)s.textContent=\'Opening Stripe checkout...\';\n  try{\n    const d=await api(\'POST\',\'/api/checkout\',{meld_code:mc.trim()});\n    window.location.href=d.url;\n  }catch(err){\n    const m=err.message||\'\';\n    if(s)s.textContent=\'\';\n    if(m.includes(\'429\')||m.toLowerCase().includes(\'too many\')){if(s)s.textContent=\'Too many attempts — take a minute and try again.\'}\n    else if(m.includes(\'404\')){if(s)s.textContent=\'No meld with that code — check the link.\'}\n    else{alert(m||\'Checkout unavailable — try again shortly.\')}\n  }\n}\n\nasync function init(){\n  const p=window.location.pathname;\n  const r=document.getElementById(\'root\');\n  if(p===\'/\'||p===\'\'||p.endsWith(\'.html\')){r.innerHTML=C();wireLanding()}\n  else if(p.startsWith(\'/m/\')){\n    _c=p.split(\'/m/\')[1];\n    const ft=(location.hash.match(/t=([0-9a-f]{64})/)||[])[1];\n    if(ft&&!_m)_m={code:_c,owner_token:ft};\n    const fk=(location.hash.match(/k=([0-9a-f]+)/)||[])[1];\n    try{\n      const hdrs=ft?{\'X-Meld-Token\':ft}:{};\n      const d=await api(\'GET\',\'/api/melds/\'+_c,null,hdrs);\n      let a=d.context_a,b=d.context_b;\n      const isEnc=!!d.encrypted||(typeof a===\'string\'&&a.startsWith(\'meld1:\'));\n      if(isEnc&&!fk&&!ft){r.innerHTML=ENC_CARD();return}\n      if(fk&&isEnc&&typeof a===\'string\'&&a.startsWith(\'meld1:\')){a=await _dec(a,fk);if(b)b=await _dec(b,fk)}\n      if(d.resolved&&ft){\n        const rr=await fetch(\'/api/melds/\'+_c+\'/result\',{headers:{\'X-Meld-Token\':ft,\'X-Meld-Client\':\'human\'}});\n        if(rr.ok){const rd=await rr.json();r.innerHTML=RD(rd.context_a,rd.context_b);startCountdown(document.getElementById(\'exp\'),rd.expires_at||d.expires_at)}\n        else{r.innerHTML=RD(a||\'(unavailable)\',\'(owner view: token rejected)\');startCountdown(document.getElementById(\'exp\'),d.expires_at)}\n      }else if(d.resolved){\n        if(a==null&&b==null){r.innerHTML=\'<div class="card" style="text-align:center;padding:3rem 2rem"><h1 style="color:var(--grey-dark)">Resolved</h1><p style="color:var(--grey-soft);margin-top:.5rem">This meld is resolved. Open the owner link (#t=) or keyed E2E link (#k=) to read contexts.</p><a href="/" style="display:inline-block;margin-top:1rem;color:var(--ink)">Create a meld</a></div>\'}\n        else{r.innerHTML=RD(a,b);startCountdown(document.getElementById(\'exp\'),d.expires_at)}\n      }else{\n        if(a==null){a=\'(Party A\\\'s context is withheld on bare GET — answer below; resolve returns both sides. Or open the owner/E2E link.)\'}\n        r.innerHTML=M(a,isEnc);if(ft){const slot=document.getElementById(\'ckbSlot\');if(slot)slot.innerHTML=\'<button id="ckb" onclick="ck()" style="margin-top:.5rem;background:none;border:1px solid var(--ink-faint);color:var(--ink);padding:.5rem 1rem;cursor:pointer;border-radius:8px;font-size:.8125rem">Check for response</button><div id="res"></div>\'}\n      }\n    }catch(e){\n      const m=e.message||\'\';\n      if(m.includes(\'410\')||m.includes(\'expired\')){r.innerHTML=\'<div class="card" style="text-align:center;padding:3rem 2rem"><h1 style="color:var(--grey-dark)">Gone</h1><p style="color:var(--grey-soft);margin-top:.5rem">This meld has dissolved.</p><a href="/" style="display:inline-block;margin-top:1rem;color:var(--ink)">Create a new one</a></div>\'}\n      else{r.innerHTML=\'<div class="card" style="text-align:center;padding:3rem 2rem"><h1 style="color:var(--grey-dark)">Not found</h1><p style="color:var(--grey-soft);margin-top:.5rem">This meld does not exist.</p><a href="/" style="display:inline-block;margin-top:1rem;color:var(--ink)">Create a meld</a></div>\'}\n    }\n  }\n  else if(p===\'/upgrade\'){r.innerHTML=UPGR()}\n  else{r.innerHTML=\'<div class="card" style="text-align:center;padding:3rem 2rem"><h1 style="color:var(--grey-dark)">Not found</h1><p style="color:var(--grey-soft);margin-top:.5rem">Page not found.</p><a href="/" style="display:inline-block;margin-top:1rem;color:var(--ink)">Create a meld</a></div>\'}\n}\ninit();\n</script>\n</body>\n</html>\n'
